import{_ as i,l as s,o as e,c as o,v as r,p as l,x as n,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"后缀数组","description":"","frontmatter":{"title":"后缀数组","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/suffix-array.md","filePath":"cs/suffix-array.md","lastUpdated":1789023840000}'),h={name:"cs/suffix-array.md"};function A(f,a,S,_,u,m){const t=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="后缀数组" tabindex="-1">后缀数组 <a class="header-anchor" href="#后缀数组" aria-label="Permalink to &quot;后缀数组&quot;">​</a></h1><div class="epigraph"><p>把文本每一个后缀的起点按字典序排好，模式查找就变成在这张起点表上二分。</p><footer>—— 据 Manber and Myers, Suffix Arrays: A New Method for On-Line String Searches, SIAM J. Comput. 1993；Kärkkäinen and Sanders, Simple Linear Work Suffix Array Construction, ICALP 2003 整理</footer></div><p><a href="/cs/space-filling-curve">上一课</a> 把网格线性化。字符串要的是「所有后缀谁更小」。<a href="/cs/kmp">KMP</a> 只预处理模式；文本多次查询或子串统计需要文本侧索引。<a href="/cs/trie">Trie</a> 可挂全部后缀但空间差。本课不写 Hilbert。缺口是后缀数组 \\(SA[i]\\) = 第 \\(i\\) 小后缀的起点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文本 \\(T[0..n)\\)（常加哨兵）。\\(n\\) 个后缀，比较两后缀最坏 \\(\\Theta(n)\\)，朴素排序 \\(\\Theta(n^2\\log n)\\)。后缀数组存排列，空间 \\(\\Theta(n)\\) 整数，远小于后缀树节点。查找 \\(P\\)：在 \\(SA\\) 上二分，每次用 \\(T[SA[\\cdot]..]\\) 与 \\(P\\) 比较，时间 \\(O(|P|\\log n)\\)。缺口是<strong>用排列代替显式树</strong>，以及后课 LCP 把比较加速。</p><p><span class="marginnote">Manber–Myers 倍增 \\(O(n\\log n)\\)。DC3/skew（Kärkkäinen–Sanders）线性时间。本课钉语义与二分查找；构造选倍增即可讲清。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>倍增：先按首字符秩，再按 \\((rank[i],rank[i+2^k])\\) 当对排序，k 增加。名次相同则后缀相等前缀更长。实现用整数排序。不要把后缀树 Ukkonen 提前当必须。</p>',8)),(e(),l(c,null,{default:n(()=>[p(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E6%96%87%E6%9C%AC%20T%22%5D%20--%3E%20SUF%5B%22n%20%E4%B8%AA%E5%90%8E%E7%BC%80%22%5D%0A%20%20SUF%20--%3E%20SA%5B%22SA%3A%20%E5%AD%97%E5%85%B8%E5%BA%8F%E4%B8%8B%E7%9A%84%E8%B5%B7%E7%82%B9%22%5D%0A%20%20P%5B%22%E6%A8%A1%E5%BC%8F%20P%22%5D%20--%3E%20BIN%5B%22%E5%9C%A8%20SA%20%E4%B8%8A%E4%BA%8C%E5%88%86%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>与哈希：期望匹配可以 Karp–Rabin，后课再收；后缀数组确定性、支持所有子串的序结构。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(SA\\) 上相邻后缀可能公共前缀很长，朴素二分反复重比——这正是下一课 LCP 与 Kasai 的缺口。逆数组 \\(ISA[SA[i]]=i\\) 把位置映回秩，构造与 LCP 都要用。</p><p>本课不把 BWT 全文写完，只承认 BWT 是 \\(SA\\) 的邻近字符排列。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不要求实现 DC3。动态插入字符使 \\(SA\\) 全失效，属动态后缀结构，主干不提前。LCP 数组是下一课必做预处理。</p><p>后课默认：静态文本子串查找可用 \\(SA\\) 二分。相邻后缀的公共前缀用 LCP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>后缀数组：后缀的字典序排列，\\(\\Theta(n)\\) 空间。</li><li>模式查找：\\(O(|P|\\log n)\\) 二分。</li><li>相邻 LCP 下一课线性算。</li><li>出处：Manber and Myers, 1993；Kärkkäinen and Sanders, ICALP 2003。</li></ul>',9))])}const k=i(h,[["render",A]]);export{T as __pageData,k as default};
